function output=run_pareto_safe_boundary_continuation(outputDir)
% Pareto-safe nested-support continuation between 1354 and 2708 deletions.
narginchk(1,1);here=fileparts(mfilename('fullpath'));root=fileparts(fileparts(here));add_paths(root,here);create_empty(outputDir);
artifactFile=fullfile(root,'results','task25_27_pipeline_20deg.mat');stage1File=fullfile(root,'results','full_integrated_layer_20deg_job22180','alpha_0p3','alpha_0p3_final.mat');anchorFile=fullfile(root,'results','survivor_compression_boundary_job22813','survivor_compression_boundary_complete.mat');priorDir=fullfile(root,'results','adaptive_survivor_boundary_job22926');
source=load(artifactFile,'cfg','machine','dij','stf','pln','map');stage1=load(stage1File,'final','supportMask');anchorData=load(anchorFile,'output');anchorData=anchorData.output;a1=load(fullfile(priorDir,'attempt_01.mat'),'death','trial');a2=load(fullfile(priorDir,'attempt_02.mat'),'death');
patient=load(source.cfg.patientFile,'ct','cst');cfg=merge_structs(default_config(),source.cfg);allowedFull=reshape(logical(stage1.supportMask),[],1);[dij,toFull,~,map]=reduce_dij_to_support(source.dij,allowedFull,source.map);for i=1:numel(map),map(i).originalGlobalIx=map(i).globalIx;map(i).globalIx=i;end
[groups,~]=build_group_index(map);[groupsFull,~]=build_group_index(source.map);D=nominal(dij);fullModel=build_matrad_dose_model(dij,patient.cst,source.pln,0);zeroTol=1e-10;wRef=reshape(double(stage1.final.w(toFull)),[],1);reference=evaluate_plan(wRef,fullModel,D,patient,cfg,source,groupsFull,toFull,stage1.final.w);anchorW=reshape(double(anchorData.w),[],1);anchor=evaluate_plan(anchorW,fullModel,D,patient,cfg,source,groupsFull,toFull,stage1.final.w);assert(anchor.activeSpots==133790&&clinical_state(anchor,reference).clinicallyFeasible);
master=unique([reshape(a1.death,[],1);reshape(a2.death,[],1)],'stable');assert(numel(master)>=2708&&all(ismember(a1.death,master(1:1354))));master=master(1:2708);warmW=reshape(double(a1.trial.w),[],1);warmW(master(1:1354))=0;
settings=struct('lowStart',1354,'highStart',2708,'firstStep',1696,'maxLevels',4,'resolution',128,'phase1CPU',40000,'phase2CPU',120000,'phase1Iter',30,'phase2Iter',180,'zeroTolerance',zeroTol,'maxRescue',512,'maxLocalSurvivors',1800);
rows=repmat(empty_row(),0,1);gates=repmat(empty_gate(),0,1);runtime=repmat(empty_runtime(),0,1);features=repmat(empty_feature(),0,1);low=settings.lowStart;high=settings.highStart;step=settings.firstStep;incW=anchorW;inc=anchor;paretoFound=false;boundaryFound=false;failureEvent=[];lastSolvedW=warmW;total=tic;
for level=1:settings.maxLevels
 incBefore=inc;
 death=master(1:step);support=anchorW>zeroTol;support(death)=false;w0=lastSolvedW;w0(death)=0;w0(~support)=0;
 rawW=anchorW;rawW(death)=0;raw=evaluate_plan(rawW,fullModel,D,patient,cfg,source,groupsFull,toFull,stage1.final.w);start=evaluate_plan(w0,fullModel,D,patient,cfg,source,groupsFull,toFull,stage1.final.w);
 [trial1,run1]=solve_phase(dij,patient.cst,source.pln,w0,support,reference,patient,cfg,source,groupsFull,toFull,stage1.final.w,settings.phase1CPU,settings.phase1Iter);state1=classify(trial1.plan,reference,incBefore,run1);
 extend=should_extend(start,trial1.plan,reference,incBefore,run1,state1);trial=trial1;run=run1;phase='INITIAL';
 if extend
  [trial2,run2]=solve_phase(dij,patient.cst,source.pln,trial1.w,support,reference,patient,cfg,source,groupsFull,toFull,stage1.final.w,settings.phase2CPU,settings.phase2Iter);trial=trial2;run=combine_runs(run1,run2);phase='EXTENDED';
 end
 state=classify(trial.plan,reference,incBefore,run);algAccepted=state.clinicallyFeasible&&state.objectivePolicy&&trial.plan.activeSpots<incBefore.activeSpots&&~(trial.plan.objective>incBefore.objective&&trial.plan.delivery.T_total>incBefore.delivery.T_total);paretoImproving=state.clinicallyFeasible&&trial.plan.activeSpots<incBefore.activeSpots&&trial.plan.objective<=incBefore.objective&&trial.plan.delivery.T_total<=incBefore.delivery.T_total;
 if state.repairable,low=step;lastSolvedW=trial.w;elseif strcmp(state.numericalClass,'DEMONSTRATED_FAILURE'),high=step;boundaryFound=true;failureEvent=struct('death',death,'trial',trial,'support',support,'run',run);else,high=step;end
 rows(end+1)=make_row(level,step,phase,state,algAccepted,paretoImproving,incBefore,raw,trial.plan,run,toc(total));gates=[gates;gate_rows(level,'raw',raw,reference);gate_rows(level,'survivor',trial.plan,reference)];runtime(end+1)=runtime_row(level,run);features(end+1)=feature_row(level,step,anchorW,death,map,groups,raw,trial.plan,incBefore,run); %#ok<AGROW>
 if algAccepted,incW=trial.w;inc=trial.plan;paretoFound=paretoFound||paretoImproving;end
 save(fullfile(outputDir,sprintf('level_%02d.mat',level)),'death','support','raw','start','trial','run','state','algAccepted','paretoImproving','-v7.3');flush(outputDir,rows,gates,runtime,features);fprintf('CONTINUATION level=%d deaths=%d phase=%s feasible=%d accepted=%d pareto=%d class=%s obj=%.6f bdt=%.3f\n',level,step,phase,state.clinicallyFeasible,algAccepted,paretoImproving,state.numericalClass,trial.plan.objective,trial.plan.delivery.T_total);
 if high-low<=settings.resolution||boundaryFound,break;end;step=round64((low+high)/2);if step<=low||step>=high,break;end
end
rescueTriggered=false;rescueSupported=false;if boundaryFound&&~isempty(failureEvent),rescueTriggered=true;historical=~(anchorW>zeroTol);[rescueIx,wWarm,proposal]=gate_aware_rescue(anchorW,failureEvent.trial.w,failureEvent.support,historical,failureEvent.death,reference,D,patient.cst,wRef,settings);save(fullfile(outputDir,'dormant_rescue_proposal.mat'),'rescueIx','proposal','-v7.3');trialSupport=failureEvent.support;trialSupport(rescueIx)=true;[repair,repairRun]=solve_phase(dij,patient.cst,source.pln,wWarm,trialSupport,reference,patient,cfg,source,groupsFull,toFull,stage1.final.w,settings.phase2CPU,settings.phase2Iter);rs=classify(repair.plan,reference,inc,repairRun);birth=rescueIx(historical(rescueIx)&repair.w(rescueIx)>zeroTol);returns=failureEvent.death(repair.w(failureEvent.death)>zeroTol);net=repair.plan.activeSpots-inc.activeSpots;rescueSupported=rs.clinicallyFeasible&&rs.objectivePolicy&&~isempty(birth)&&net<0&&numel(returns)<.9*numel(failureEvent.death);save(fullfile(outputDir,'dormant_rescue_result.mat'),'repair','repairRun','rs','birth','returns','net','rescueSupported','-v7.3');end
if boundaryFound,boundaryLabel='SURVIVOR_COMPRESSION_BOUNDARY_FOUND';elseif any(strcmp({rows.numericalClass},'NUMERICALLY_INCONCLUSIVE')),boundaryLabel='INCONCLUSIVE';else,boundaryLabel='SURVIVOR_COMPRESSION_BOUNDARY_NOT_FOUND';end;if paretoFound,paretoLabel='PARETO_IMPROVING_TRANSITION_FOUND';else,paretoLabel='NO_PARETO_IMPROVEMENT';end
output=struct('boundaryLabel',boundaryLabel,'paretoLabel',paretoLabel,'rescueTriggered',rescueTriggered,'rescueSupported',rescueSupported,'settings',settings,'lowRepairable',low,'highUnresolvedOrFailed',high,'incumbentW',incW,'incumbent',inc,'anchor',anchor,'rows',rows,'gates',gates,'runtime',runtime,'features',features,'wallSeconds',toc(total));save(fullfile(outputDir,'pareto_safe_boundary_continuation_complete.mat'),'output','-v7.3');flush(outputDir,rows,gates,runtime,features);write_report(outputDir,output);fprintf('FINAL_LABELS: %s | %s | DORMANT_TRIGGERED=%d\n',boundaryLabel,paretoLabel,rescueTriggered);
end

function [sol,run]=solve_phase(dij,cst,pln,wStart,support,reference,patient,cfg,source,groupsFull,toFull,wTemplate,cpu,iters)
[dijR,r2f]=reduce_dij_to_support(dij,support);m=build_matrad_dose_model(dijR,cst,pln,0);D=nominal(dijR);sp=build_clinical_gate_spec(D,cst,reference.dose,2,0.2);set=struct('ipopt',struct('max_iter',iters,'max_cpu_time',cpu,'print_level',3,'acceptable_iter',8,'acceptable_obj_change_tol',1e-5));run=solve_clinical_gate_ipopt(m,wStart(r2f),D,sp,set);w=zeros(double(dij.totalNumOfBixels),1);w(r2f)=run.w;plan=evaluate_plan(w,build_matrad_dose_model(dij,cst,pln,0),nominal(dij),patient,cfg,source,groupsFull,toFull,wTemplate);sol=struct('w',w,'plan',plan,'support',support);
end
function s=classify(p,ref,inc,run),g=clinical_state(p,ref);s=g;s.objectivePolicy=p.objective<=1.02*ref.objective;s.numericallyStationary=run.numericallyStationary;s.repairable=s.clinicallyFeasible&&s.objectivePolicy;if s.repairable,s.numericalClass='REPAIRABLE_FEASIBLE_POINT';elseif run.status==2||any(run.status==[0 1])&&~s.clinicallyFeasible,s.numericalClass='DEMONSTRATED_FAILURE';else,s.numericalClass='NUMERICALLY_INCONCLUSIVE';end;s.objectiveChangeVsIncumbent=p.objective-inc.objective;s.bdtChangeVsIncumbent=p.delivery.T_total-inc.delivery.T_total;end
function tf=should_extend(start,p,ref,inc,run,state),ceiling=1.02*ref.objective;progress=p.objective<start.objective-1e-6*max(1,abs(start.objective));near=p.objective<=1.20*ceiling;dominated=p.objective>inc.objective&&p.delivery.T_total>inc.delivery.T_total;tf=(~state.repairable&&(progress||near||run.primalInfeasibility>1e-6))||(state.repairable&&dominated&&progress&&near);end
function c=combine_runs(a,b),c=b;c.wallSeconds=a.wallSeconds+b.wallSeconds;c.iterations=a.iterations+b.iterations;f=fieldnames(c.callbackCounts);for i=1:numel(f),if isfield(a.callbackCounts,f{i}),c.callbackCounts.(f{i})=a.callbackCounts.(f{i})+b.callbackCounts.(f{i});end,end;end
function s=clinical_state(p,r),[pass,worst,detail]=dose_quality(p.dose,r.dose);s=struct('clinicallyFeasible',pass&&p.maxConstraintViolation<=1e-6,'dosePass',pass,'constraintPass',p.maxConstraintViolation<=1e-6,'worstAdverse',worst,'detail',{detail});end
function p=evaluate_plan(w,model,D,patient,cfg,source,groupsFull,toFull,wTemplate),[f,~,d]=evaluate_matrad_dose_model(model,w,false);z=zeros(size(wTemplate));z(toFull)=w;p=struct('objective',f,'maxConstraintViolation',d.maxConstraintViolation,'dose',compute_dvh_metrics(full(D*w),patient.ct,patient.cst,cfg),'delivery',compute_delivery_metrics(z,source.map,groupsFull,cfg,source.machine),'activeSpots',nnz(w>1e-10),'activeLayers',count_layers(w,build_groups(source.map,toFull),1e-10));end
function [pass,worst,rows]=dose_quality(c,r),pass=true;worst=0;rows={};for i=1:numel(c.structures),a=r.structures(i);b=c.structures(i);if a.isTarget,keys={'D95','D98'};sense='lower';elseif strcmpi(a.type,'OAR')&&~ismember(upper(a.name),{'BODY','EXTERNAL'}),keys={'Dmean','Dmax'};sense='upper';else,continue;end;for k=1:numel(keys),m=keys{k};if strcmp(sense,'lower'),lim=.98*a.(m);ok=b.(m)>=lim;adv=max(0,100*(a.(m)-b.(m))/max(abs(a.(m)),eps));else,lim=a.(m)+max(.2,.02*max(abs(a.(m)),1));ok=b.(m)<=lim;adv=max(0,100*(b.(m)-a.(m))/max(abs(a.(m)),eps));end;rows(end+1,:)={a.name,m,b.(m),lim,ok};pass=pass&&ok;worst=max(worst,adv);end,end,end
function r=empty_row(),r=struct('level',0,'proposedDeaths',0,'phase','','clinicallyFeasible',false,'algorithmicallyAccepted',false,'numericallyStationary',false,'numericalClass','','positiveSpots',0,'activeLayers',0,'objective',0,'objectiveChangeVsIncumbent',0,'bdt',0,'bdtChangeVsIncumbent',0,'paretoDominatedRegression',false,'paretoImproving',false,'iterations',0,'primalInfeasibility',0,'dualInfeasibility',0,'wallSeconds',0,'objectiveCalls',0,'gradientCalls',0,'constraintCalls',0,'jacobianCalls',0);end
function r=make_row(k,n,phase,s,accepted,pareto,inc,raw,p,run,wall),r=empty_row();r.level=k;r.proposedDeaths=n;r.phase=phase;r.clinicallyFeasible=s.clinicallyFeasible;r.algorithmicallyAccepted=accepted;r.numericallyStationary=s.numericallyStationary;r.numericalClass=s.numericalClass;r.positiveSpots=p.activeSpots;r.activeLayers=p.activeLayers;r.objective=p.objective;r.objectiveChangeVsIncumbent=p.objective-inc.objective;r.bdt=p.delivery.T_total;r.bdtChangeVsIncumbent=p.delivery.T_total-inc.delivery.T_total;r.paretoDominatedRegression=p.objective>inc.objective&&p.delivery.T_total>inc.delivery.T_total;r.paretoImproving=pareto;r.iterations=run.iterations;r.primalInfeasibility=run.primalInfeasibility;r.dualInfeasibility=run.dualInfeasibility;r.wallSeconds=wall;r.objectiveCalls=run.callbackCounts.objective;r.gradientCalls=run.callbackCounts.gradient;r.constraintCalls=run.callbackCounts.constraints;r.jacobianCalls=run.callbackCounts.jacobian; %#ok<INUSD>
end
function r=empty_feature(),r=struct('level',0,'proposedDeaths',0,'totalDeletedWeight',0,'affectedLayers',0,'fullyRemovedLayers',0,'affectedControlPoints',0,'targetD95RawChange',0,'targetD98RawChange',0,'rawObjectiveChange',0,'repairedObjectiveChange',0,'permanentDeathsPerSolve',0,'bdtSecondsReducedPerWallHour',0);end
function r=feature_row(k,n,w,d,map,groups,raw,p,inc,run),r=empty_feature();r.level=k;r.proposedDeaths=n;r.totalDeletedWeight=sum(w(d));layer=zeros(numel(w),1);for i=1:numel(groups),layer(groups(i).ix)=i;end;a=unique(layer(d));r.affectedLayers=numel(a);for i=reshape(a,1,[]),ix=groups(i).ix;r.fullyRemovedLayers=r.fullyRemovedLayers+all(ismember(ix(w(ix)>1e-10),d));end;r.affectedControlPoints=numel(unique([map(d).cpIndex]));q=find(strcmp({raw.dose.structures.name},'PTV_68'),1);r.targetD95RawChange=raw.dose.structures(q).D95-inc.dose.structures(q).D95;r.targetD98RawChange=raw.dose.structures(q).D98-inc.dose.structures(q).D98;r.rawObjectiveChange=raw.objective-inc.objective;r.repairedObjectiveChange=p.objective-inc.objective;r.permanentDeathsPerSolve=inc.activeSpots-p.activeSpots;r.bdtSecondsReducedPerWallHour=(inc.delivery.T_total-p.delivery.T_total)/max(run.wallSeconds/3600,eps);end
function r=empty_gate(),r=struct('level',0,'phase','','structure','','metric','','value',0,'limit',0,'pass',false);end
function r=gate_rows(k,phase,p,ref),[~,~,d]=dose_quality(p.dose,ref.dose);r=repmat(empty_gate(),size(d,1),1);for i=1:size(d,1),r(i)=struct('level',k,'phase',phase,'structure',d{i,1},'metric',d{i,2},'value',d{i,3},'limit',d{i,4},'pass',d{i,5});end,end
function r=empty_runtime(),r=struct('level',0,'solverWallSeconds',0,'iterations',0,'objectiveCalls',0,'gradientCalls',0,'constraintCalls',0,'jacobianCalls',0);end
function r=runtime_row(k,s),r=empty_runtime();r.level=k;r.solverWallSeconds=s.wallSeconds;r.iterations=s.iterations;r.objectiveCalls=s.callbackCounts.objective;r.gradientCalls=s.callbackCounts.gradient;r.constraintCalls=s.callbackCounts.constraints;r.jacobianCalls=s.callbackCounts.jacobian;end
function flush(o,a,b,c,d),if ~isempty(a),writetable(struct2table(a,'AsArray',true),fullfile(o,'continuation_trials.csv'));end;if ~isempty(b),writetable(struct2table(b,'AsArray',true),fullfile(o,'clinical_gate_trajectory.csv'));end;if ~isempty(c),writetable(struct2table(c,'AsArray',true),fullfile(o,'runtime_evaluations.csv'));end;if ~isempty(d),writetable(struct2table(d,'AsArray',true),fullfile(o,'deletion_features.csv'));end,end
function write_report(o,x),f=fopen(fullfile(o,'PARETO_SAFE_BOUNDARY_CONTINUATION_REPORT.md'),'w');c=onCleanup(@()fclose(f));fprintf(f,'# Pareto-safe boundary continuation\n\n- boundary: `%s`\n- incumbent result: `%s`\n- dormant rescue triggered: %d\n- low repairable: %d\n- high unresolved/failed: %d\n- incumbent spots/layers: %d/%d\n- incumbent objective: %.9g\n- incumbent BDT: %.3f s\n',x.boundaryLabel,x.paretoLabel,x.rescueTriggered,x.lowRepairable,x.highUnresolvedOrFailed,x.incumbent.activeSpots,x.incumbent.activeLayers,x.incumbent.objective,x.incumbent.delivery.T_total);end
function [rescue,wWarm,p]=gate_aware_rescue(wInc,wFail,support,historical,deaths,reference,D,cst,wRef,s),spec=build_clinical_gate_spec(D,cst,reference.dose,2,.2);[vals,J]=evaluate_clinical_gates(D,wFail,spec,true);A=sparse(J);b=zeros(numel(spec),1);for i=1:numel(spec),if strcmp(spec(i).sense,'lower'),A(i,:)=-A(i,:);b(i)=vals(i)-spec(i).limit;else,b(i)=spec(i).limit-vals(i);end,end;importance=max(abs(A),[],1)';surv=top(importance.*max(wFail,1e-8),support&(wFail>s.zeroTolerance),s.maxLocalSurvivors);eligible=unique([find(historical);deaths(:)],'stable');Jix=unique([surv;eligible],'stable');isE=ismember(Jix,eligible);Aj=A(:,Jix);lb=-wFail(Jix);lb(isE)=0;ub=max([abs(wFail(Jix)),abs(wRef(Jix)),ones(numel(Jix),1)],[],2);lp=optimoptions('linprog','Display','none');[x,~,ef]=linprog([zeros(numel(Jix),1);1],[Aj,-max(.05,abs(b))],b,[],[],[lb;0],[ub;10],lp);rho=Inf;if ef>0,rho=x(end);end;rescue=zeros(0,1);wWarm=wFail;if rho<=1e-6,cand=find(isE&x(1:end-1)>1e-8);[~,q]=sort(x(cand),'descend');cand=cand(q(1:min(s.maxRescue,numel(q))));rescue=Jix(cand);wWarm(rescue)=max(wWarm(rescue),x(cand));end;p=struct('rho',rho,'rescueIx',rescue,'eligibleIx',eligible); %#ok<INUSD>
end
function q=round64(x),q=64*round(x/64);end
function D=nominal(d),D=d.physicalDose;if iscell(D),D=D{1};end,end
function g=build_groups(map,toFull),m=map(toFull);for i=1:numel(m),m(i).globalIx=i;end;g=build_group_index(m);end
function n=count_layers(w,g,t),n=0;for i=1:numel(g),n=n+any(w(g(i).ix)>t);end,end
function ix=top(score,mask,k),q=find(mask&isfinite(score));[~,o]=sort(score(q),'descend');ix=q(o(1:min(k,numel(o))));end
function add_paths(root,here),f={'config','planning','mapping','objective','delivery','reduction','evaluation','integrated','robustness'};for i=1:numel(f),addpath(fullfile(root,f{i}));end;addpath(fullfile(root,'experiments','repeated_dormant_replacement'));addpath(here);end
function create_empty(d),if exist(d,'dir')==7,e=dir(d);e=e(~ismember({e.name},{'.','..'}));assert(isempty(e));else,mkdir(d);end,end
function m=merge_structs(a,b),m=a;f=fieldnames(b);for i=1:numel(f),k=f{i};if isfield(m,k)&&isstruct(m.(k))&&isstruct(b.(k)),m.(k)=merge_structs(m.(k),b.(k));else,m.(k)=b.(k);end,end,end
